import{_ as d,a0 as o,w as a,s as l,I as t,x as i,a1 as r,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"系統之鍬sysdig：Linux服務器監控和排障利器 | LCTT x X-CMD","titleTemplate":false,"description":"系統之鍬sysdig：Linux服務器監控和排障利器 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系統之鍬sysdig：Linux服務器監控和排障利器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系統之鍬sysdig：Linux服務器監控和排障利器 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141014 How to monitor and troubleshoot a Linux server using sysdig","title":"系統之鍬sysdig：Linux服務器監控和排障利器","tag":"201411","desc":""},"relativePath":"201411/20141014 How to monitor and troubleshoot a Linux server using sysdig.md","filePath":"[post].md"}'),g={name:"201411/20141014 How to monitor and troubleshoot a Linux server using sysdig.md"};function y(m,s,u,c,f,x){const e=o("Link");return a(),l("div",null,[s[19]||(s[19]=t("h1",{id:"系統之鍬sysdig-linux服務器監控和排障利器",tabindex:"-1"},[i("系統之鍬sysdig：Linux服務器監控和排障利器 "),t("a",{class:"header-anchor",href:"#系統之鍬sysdig-linux服務器監控和排障利器","aria-label":"Permalink to “系統之鍬sysdig：Linux服務器監控和排障利器”"},"​")],-1)),s[20]||(s[20]=t("p",null,"當你需要追蹤某個進程產生和接收的系統調用時，首先浮現在你腦海中的是什麼？你可能會想到strace，那麼你是對的。你會使用什麼樣的命令列工具來監控原始網絡通信呢？如果你想到了tcpdump，你又作出了一個極佳的選擇。而如果你碰到必須追蹤打開的文件（在Unix意義上：一切皆文件）的需求，可能你會使用lsof。",-1)),t("p",null,[s[1]||(s[1]=i("strace、tcpdump以及lsof，確實是些偉大的工具，它們應該成為每個系統管理員工具集之中的一部分，而這也正是你為什麼應該愛上",-1)),r(e,{href:"http://www.sysdig.org/"},{default:p(()=>[...s[0]||(s[0]=[i("sysdig",-1)])]),_:1}),s[2]||(s[2]=i("的原因。它是一個強大的開源工具，用於系統級別的勘察和排障，它的創建者在介紹它時稱之為“strace+tcpdump+lsof+上面點綴着lua櫻桃的絕妙醬汁”。拋開幽默不説，sysdig的最棒特性之一在於，它不僅能分析Linux系統的“現場”狀態，也能將該狀態保存為轉儲文件以供離線檢查。更重要的是，你可以自定義sysdig的行為，或者甚至通過內建的（你也可以自己編寫）名為鑿子（chisel）的小腳本增強其功能。單獨的鑿子可以以腳本指定的各種風格分析sysdig捕獲的事件流。",-1))]),s[21]||(s[21]=n(`<p>在本教程中，我們將探索sysdig的安裝及其基本用法，在Linux上實施系統監控和排障。</p><h3 id="安裝sysdig" tabindex="-1">安裝Sysdig <a class="header-anchor" href="#安裝sysdig" aria-label="Permalink to “安裝Sysdig”">​</a></h3><p>對於本教程，由於為了簡便、縮短安裝流程以及版本的不可知，我們將選擇使用官方網站提供的自動化安裝過程。在自動化過程中，安裝腳本會自動檢測操作系統並安裝必需的依賴包。</p><p>以root身份運行以下命令來從官方apt/yum倉庫安裝sysdig：</p><pre><code># curl -s https://s3.amazonaws.com/download.draios.com/stable/install-sysdig | bash 
</code></pre><p><img src="https://farm6.staticflickr.com/5616/15334678580_99c5d38328_z.jpg" alt=""></p><p>安裝完成後，我們可以通過以下方法調用sysdig來感受一下它：</p><pre><code># sysdig 
</code></pre><p>我們的屏幕將馬上被系統上發生的所有事件填滿，對於這些信息，不便於我們做更多操作。要進一步處理，我們可以運行：</p><pre><code># sysdig -cl | less 
</code></pre><p>來查看可用的鑿子列表。</p><p><img src="https://farm4.staticflickr.com/3938/15334678610_e5956a26e8_z.jpg" alt=""></p><p>默認有以下類目可用，各個類目中分佈有多個內建的鑿子。</p><ul><li>CPU Usage：CPU使用量</li><li>Errors：錯誤</li><li>I/O</li><li>Logs：日誌</li><li>Misc：混雜</li><li>Net：網絡</li><li>Performance：性能</li><li>Security：安全</li><li>System State：系統狀態</li></ul><p>要顯示指定鑿子上的信息（包括詳細的命令列用法），運行以下命令：</p><pre><code># sysdig -cl [鑿子名稱] 
</code></pre><p>例如，我們可以檢查“網絡”類目下關於spy_port鑿子的信息：</p><pre><code># sysdig -i spy_port 
</code></pre><p><img src="https://farm4.staticflickr.com/3945/15521424095_0365bf20c3_z.jpg" alt=""></p><p>鑿子可以通過過濾器（可同時應用於實時數據和記錄文件）組合，以獲取更多有用的輸出。</p><p>過濾器遵從“類.字段”結構。例如：</p><ul><li><strong>fd.cip</strong>：客户端IP地址。</li><li><strong>evt.dir</strong>：事件方向，可以是<code>&gt;</code>用於進入事件，或<code>&lt;</code>用於退出事件。</li></ul><p>完整的過濾器列表可以通過以下命令顯示：</p><pre><code># sysdig -l 
</code></pre><p>在本教程剩餘部分，我將演示幾個sysdig的使用案例。</p><h3 id="sysdig實例-服務器性能排障" tabindex="-1">Sysdig實例： 服務器性能排障 <a class="header-anchor" href="#sysdig實例-服務器性能排障" aria-label="Permalink to “Sysdig實例： 服務器性能排障”">​</a></h3><p>假定你的服務器發生了性能問題（如，沒有回應，或者重大的回應延遲）。你可以使用瓶頸鑿子來顯示當前10個最慢系統調用的列表。</p><p>使用以下命令在存活服務器上進行實時檢查。“-c”標識，後跟鑿子名稱告訴sysdig運行指定的鑿子。</p><pre><code># sysdig -c bottlenecks 
</code></pre><p>或者，你可以離線對服務器實施性能分析。在此種情況下，你可以保存完整的sysdig記錄到文件，然後像下面這樣針對記錄運行瓶頸鑿子。</p><p>首先，保存sysdige記錄（使用Ctrl+c來停止收集）：</p><pre><code># sysdig -w trace.scap 
</code></pre><p>收集完記錄後，你可以運行以下命令來檢查捕獲間隔中最慢的系統調用：</p><pre><code># sysdig -r trace.scap -c bottlenecks 
</code></pre><p><img src="https://farm6.staticflickr.com/5611/15334678670_ebbe93265e_z.jpg" alt=""></p><p>你需要關注欄#2，#3和#4，這些分別表示執行時間、進程名和PID。</p><h3 id="sysdig實例-監控交互用户活動" tabindex="-1">Sysdig實例： 監控交互用户活動 <a class="header-anchor" href="#sysdig實例-監控交互用户活動" aria-label="Permalink to “Sysdig實例： 監控交互用户活動”">​</a></h3><p>假定你作為系統管理員想要監控系統中交互的用户活動（如，用户在命令列輸入了什麼命令，以及用户去了什麼目錄），這時spy_user鑿子就派上用場了。</p><p>讓我們首先通過一些額外選項來收集一個sysdig記錄。</p><pre><code># sysdig -s 4096 -z -w /mnt/sysdig/$(hostname).scap.gz 
</code></pre><ul><li>“-s 4096”告訴sysdig每個事件捕獲4096字節。</li><li>“-z” （與“-w”一起使用）為記錄文件啓用壓縮。</li><li>“-w <code>&lt;trace-file&gt;</code>”保存sysdig記錄到指定的文件。</li></ul><p>在上面的例子中，我們自定義了基於每個主機的壓縮的記錄文件的名稱。記住，你可以在任何時候按下Ctrl+c來打斷sysdig的執行。</p><p>在我們收集到了合理數量的數據後，我們可以通過運行以下命令來查看每個用户的交互活動：</p><pre><code># sysdig -r /mnt/sysdig/debian.scap.gz -c spy_users 
</code></pre><p><img src="https://farm4.staticflickr.com/3932/15518254291_5c9671ca41_z.jpg" alt=""></p><p>上面輸出的第一欄表示與指定用户的活動相關進程的PID。</p><p>如果你想要定位一個指定的用户，以及只監控該用户的活動又怎麼樣呢？你可以通過用户名對spy_users鑿子的結果進行過濾：</p><pre><code># sysdig -r /mnt/sysdig/debian.scap.gz -c spy_users &quot;user.name=xmodulo&quot; 
</code></pre><p><img src="https://farm4.staticflickr.com/3944/15498248556_66d15422b1_z.jpg" alt=""></p><h3 id="sysdig實例-監控文件i-o" tabindex="-1">Sysdig實例： 監控文件I/O <a class="header-anchor" href="#sysdig實例-監控文件i-o" aria-label="Permalink to “Sysdig實例： 監控文件I/O”">​</a></h3><p>我們可以使用“-p”標識來自定義sysdig記錄的輸出格式，並指定雙引號括起來的想要的字段（如用户名、進程名，以及文件或套接口名稱）。在本例中，我們將創建一個記錄文件，該文件將只包含在家目錄中的寫入事件（我們今後可以使用“sysdig -r writetrace.scap.gz”來檢測該文件）。</p><pre><code># sysdig -p &quot;%user.name %proc.name %fd.name&quot; &quot;evt.type=write and fd.name contains /home/&quot; -z -w writetrace.scap.gz 
</code></pre><p><img src="https://farm6.staticflickr.com/5610/15498248586_de5f5fc93d_z.jpg" alt=""></p><h3 id="sysdig實例-監控網絡i-o" tabindex="-1">Sysdig實例： 監控網絡I/O <a class="header-anchor" href="#sysdig實例-監控網絡i-o" aria-label="Permalink to “Sysdig實例： 監控網絡I/O”">​</a></h3><p>作為服務器排障的一部分，你可能想要監聽網絡通信，此工作通常由tcpdump做。對於sysdig，可以很容易進行通信嗅探，其風格更為對用户友好。</p><p>例如，你可以檢查由特定IP地址，特定進程（如apache2）提供的數據（ASCII編碼格式）：</p><pre><code># sysdig -s 4096 -A -c echo_fds fd.cip=192.168.0.100 -r /mnt/sysdig/debian.scap.gz proc.name=apache2 
</code></pre><p>如果你想要監控原生數據傳輸（二進制格式），請把“-A”替換為“-X”：</p><pre><code># sysdig -s 4096 -X -c echo_fds fd.cip=192.168.0.100 -r /mnt/sysdig/debian.scap.gz proc.name=apache2 
</code></pre>`,59)),t("p",null,[s[4]||(s[4]=i("要獲取更多信息、實例以及案例分析，你可以查閲",-1)),r(e,{href:"http://www.sysdig.org/"},{default:p(()=>[...s[3]||(s[3]=[i("項目網站",-1)])]),_:1}),s[5]||(s[5]=i("。相信我，會有着無限可能，但請不要僅僅侷限於我所寫的這些。安裝sysdig，請從今天開始深入挖掘吧！",-1))]),s[22]||(s[22]=t("hr",null,null,-1)),t("p",null,[s[7]||(s[7]=i("via: ",-1)),r(e,{href:"http://xmodulo.com/monitor-troubleshoot-linux-server-sysdig.html"},{default:p(()=>[...s[6]||(s[6]=[i("http://xmodulo.com/monitor-troubleshoot-linux-server-sysdig.html",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=i("作者：",-1)),r(e,{href:"http://xmodulo.com/author/gabriel"},{default:p(()=>[...s[8]||(s[8]=[i("Gabriel Cánepa",-1)])]),_:1}),s[12]||(s[12]=i(" 譯者：",-1)),r(e,{href:"https://github.com/GOLinux"},{default:p(()=>[...s[9]||(s[9]=[i("GOLinux",-1)])]),_:1}),s[13]||(s[13]=i(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=i("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[i("Linux中國",-1)])]),_:1}),s[18]||(s[18]=i(" 榮譽推出",-1))])])}const w=d(g,[["render",y]]);export{L as __pageData,w as default};
